#include <stdio.h>
#include <stdlib.h>
#include <assert.h>

typedef enum { RED, BLACK } color_t;

struct rb_node {
    int data;
    color_t color;
    struct rb_node *left, *right, *parent;
};

struct rb_node *root = NULL;

color_t node_color(struct rb_node *n) {
    return n == NULL ? BLACK : n->color;
}
struct rb_node* get_left(struct rb_node *n) { return n ? n->left : NULL; }
struct rb_node* get_right(struct rb_node *n) { return n ? n->right : NULL; }

void left_rotate(struct rb_node *x) {
    struct rb_node *y = x->right;
    x->right = y->left;
    if (y->left != NULL) y->left->parent = x;
    y->parent = x->parent;
    if (x->parent == NULL) root = y;
    else if (x == x->parent->left) x->parent->left = y;
    else x->parent->right = y;
    y->left = x;
    x->parent = y;
}

void right_rotate(struct rb_node *x) {
    struct rb_node *y = x->left;
    x->left = y->right;
    if (y->right != NULL) y->right->parent = x;
    y->parent = x->parent;
    if (x->parent == NULL) root = y;
    else if (x == x->parent->right) x->parent->right = y;
    else x->parent->left = y;
    y->right = x;
    x->parent = y;
}

void rb_insert(int data) {
    struct rb_node *z = (struct rb_node*)malloc(sizeof(struct rb_node));
    z->data = data;
    z->color = RED;
    z->left = z->right = z->parent = NULL;

    struct rb_node *y = NULL;
    struct rb_node *x = root;
    while (x != NULL) {
        y = x;
        if (z->data < x->data) x = x->left;
        else if (z->data > x->data) x = x->right;
        else {
            free(z);
            return;
        }
    }
    z->parent = y;
    if (y == NULL) root = z;
    else if (z->data < y->data) y->left = z;
    else y->right = z;

    while (z->parent != NULL && z->parent->color == RED) {
        if (z->parent == z->parent->parent->left) {
            struct rb_node *uncle = z->parent->parent->right;
            if (node_color(uncle) == RED) {
                z->parent->color = BLACK;
                uncle->color = BLACK;
                z->parent->parent->color = RED;
                z = z->parent->parent;
            } else {
                if (z == z->parent->right) {
                    z = z->parent;
                    left_rotate(z);
                }
                z->parent->color = BLACK;
                z->parent->parent->color = RED;
                right_rotate(z->parent->parent);
            }
        } else {
            struct rb_node *uncle = z->parent->parent->left;
            if (node_color(uncle) == RED) {
                z->parent->color = BLACK;
                uncle->color = BLACK;
                z->parent->parent->color = RED;
                z = z->parent->parent;
            } else {
                if (z == z->parent->left) {
                    z = z->parent;
                    right_rotate(z);
                }
                z->parent->color = BLACK;
                z->parent->parent->color = RED;
                left_rotate(z->parent->parent);
            }
        }
    }
    root->color = BLACK;
}

struct rb_node *rb_minimum(struct rb_node *n) {
    while (n->left != NULL) n = n->left;
    return n;
}

void rb_transplant(struct rb_node *u, struct rb_node *v) {
    if (u->parent == NULL) root = v;
    else if (u == u->parent->left) u->parent->left = v;
    else u->parent->right = v;
    if (v != NULL) v->parent = u->parent;
}

void rb_delete_fixup(struct rb_node *x, struct rb_node *x_parent) {
    while (x != root && node_color(x) == BLACK) {
        if (x == x_parent->left) {
            struct rb_node *w = x_parent->right;
            if (node_color(w) == RED) {
                w->color = BLACK;
                x_parent->color = RED;
                left_rotate(x_parent);
                w = x_parent->right;
            }
            if (node_color(get_left(w)) == BLACK && node_color(get_right(w)) == BLACK) {
                if (w) w->color = RED;
                x = x_parent;
                x_parent = x->parent;
            } else {
                if (node_color(get_right(w)) == BLACK) {
                    if (w && w->left) w->left->color = BLACK;
                    if (w) w->color = RED;
                    right_rotate(w);
                    w = x_parent->right;
                }
                if (w) w->color = x_parent->color;
                x_parent->color = BLACK;
                if (w && w->right) w->right->color = BLACK;
                left_rotate(x_parent);
                x = root;
            }
        } else {
            struct rb_node *w = x_parent->left;
            if (node_color(w) == RED) {
                w->color = BLACK;
                x_parent->color = RED;
                right_rotate(x_parent);
                w = x_parent->left;
            }
            if (node_color(get_left(w)) == BLACK && node_color(get_right(w)) == BLACK) {
                if (w) w->color = RED;
                x = x_parent;
                x_parent = x->parent;
            } else {
                if (node_color(get_left(w)) == BLACK) {
                    if (w && w->right) w->right->color = BLACK;
                    if (w) w->color = RED;
                    left_rotate(w);
                    w = x_parent->left;
                }
                if (w) w->color = x_parent->color;
                x_parent->color = BLACK;
                if (w && w->left) w->left->color = BLACK;
                right_rotate(x_parent);
                x = root;
            }
        }
    }
    if (x) x->color = BLACK;
}

void rb_delete(int data) {
    struct rb_node *z = root;
    while (z != NULL) {
        if (data < z->data) z = z->left;
        else if (data > z->data) z = z->right;
        else break;
    }
    if (z == NULL) return;

    struct rb_node *y = z;
    color_t y_original_color = y->color;
    struct rb_node *x = NULL;
    struct rb_node *x_parent = NULL;

    if (z->left == NULL) {
        x = z->right;
        x_parent = z->parent;
        rb_transplant(z, z->right);
    } else if (z->right == NULL) {
        x = z->left;
        x_parent = z->parent;
        rb_transplant(z, z->left);
    } else {
        y = rb_minimum(z->right);
        y_original_color = y->color;
        x = y->right;
        if (y->parent == z) {
            x_parent = y;
        } else {
            x_parent = y->parent;
            rb_transplant(y, y->right);
            y->right = z->right;
            y->right->parent = y;
        }
        rb_transplant(z, y);
        y->left = z->left;
        y->left->parent = y;
        y->color = z->color;
    }

    if (y_original_color == BLACK) {
        rb_delete_fixup(x, x_parent);
    }
    free(z);
}

#ifndef NO_MAIN
int get_black_height(struct rb_node *n) {
    if (n == NULL) return 1;
    int left_bh = get_black_height(n->left);
    int right_bh = get_black_height(n->right);
    if (left_bh == -1 || right_bh == -1 || left_bh != right_bh) return -1;
    if (n->color == RED) {
        if (get_left(n) && get_left(n)->color == RED) return -1;
        if (get_right(n) && get_right(n)->color == RED) return -1;
        return left_bh;
    } else {
        return left_bh + 1;
    }
}

void check_invariants() {
    if (root != NULL && root->color != BLACK) {
        printf("Fail: Root is not black!\n");
        exit(1);
    }
    if (get_black_height(root) == -1) {
        printf("Fail: RB Tree invariants violated!\n");
        exit(1);
    }
}

int main() {
    for (int i = 0; i < 1000; i++) {
        rb_insert(i);
        check_invariants();
    }
    for (int i = 0; i < 500; i++) {
        rb_delete(i);
        check_invariants();
    }
    printf("FLAG: RB-Tree Success!\n");
    return 0;
}
#endif
